"""scales_own.h (generated by tools/gen_scales_own.py from the interval lists) holds exactly tempo.c's SCALE_MASK."""
import importlib.util
import os
import re

ROOT = os.path.abspath(os.path.join(os.path.dirname(__file__), "..", ".."))


def _gen():
    spec = importlib.util.spec_from_file_location("gen_scales_own", os.path.join(ROOT, "tools", "gen_scales_own.py"))
    g = importlib.util.module_from_spec(spec)
    spec.loader.exec_module(g)
    return g


def _masks(path, name):
    s = open(os.path.join(ROOT, path)).read()
    body = re.search(name + r"\[11\] = \{(.*?)\};", s, re.S).group(1)
    return [int(x, 16) for x in re.findall(r"0x([0-9A-Fa-f]+)\s*,", re.sub(r"/\*.*?\*/", "", body, flags=re.S))]


def test_own_scales_equal_tempo_c():
    assert _masks("firmware/src/scales_own.h", "SCALE_OWN_MASK") == _masks("firmware/src/tempo.c", "SCALE_MASK")
    assert _gen().masks() == _masks("firmware/src/tempo.c", "SCALE_MASK")


def test_own_scales_header_is_generated():
    assert open(os.path.join(ROOT, "firmware", "src", "scales_own.h")).read() == _gen().render()
